        normalizedProjectRoot: async (cwd: string | undefined) =>
          typeof cwd === "string" && cwd !== "" ? cwd : undefined,
        saveUserState: async () => {},
        emitStatus: () => {},
        catalogCachePath: (root: string) => join(root, ".dsh-mcp-symlink-test.json"),
