  it("summary() 全量无明文（含 runtime 条目亦投影）", () => {
    installPorts();
    const manager = managerWith([stdioSecret("g1")]);
    (manager as unknown as { runtimeRegistry: Map<string, ServerConfig> }).runtimeRegistry.set(
      "rt1",
