    expect(out.args).toEqual(["-y", "pkg"]);
    expect(out.hasSecrets).toBe(false);
  });

  it("投影整体回写 update 时既有 args 不变、盘上无占位符", async () => {
    installPorts();
    const server = argsServer(["--token", ARG_SECRET]);
